use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let mut jobs = Vec::new();
    for value in input.as_array().unwrap() {
        let job: Vec<i64> = value.as_array().unwrap().iter().map(|v| v.as_i64().unwrap()).collect();
        jobs.push(job);
    }

    jobs.sort_by(|a, b| a[0].cmp(&b[0]));

    let mut finish_times = Vec::new();
    let mut current_time = 0;
    for job in jobs {
        current_time = std::cmp::max(current_time, job[0]);
        current_time += job[1];
        finish_times.push(current_time);
    }

    let finish_times: Value = serde_json::to_value(finish_times).unwrap();
    finish_times
}
